/**
 * 查词总入口：本机 API（牛津）→ 网站自带的离线词库 → 在线词典 → 本地兜底。
 *
 * 本机开着 API 时第一条就够了（内容最全）；线上是静态站，/v1 是 404，就落到
 * 随站点发布的离线词库上；再不行才问在线源（它在国外网络才通）；全落空才用
 * 本地兜底，并且明说这是「示例」，不让人以为真查到了词。
 *
 * 词典卡片和词汇积累页都从这里走，几条路的先后只写这一遍。
 */
import type { LanguageInsight } from "@leafia/shared";
import { fallbackInsight } from "../data/demo";
import { api } from "./api";
import { lookupOfflineDictionary } from "./offlineDictionary";
import { lookupOnlineDictionary } from "./onlineDictionary";

export interface DictionaryLookupResult {
  insight: LanguageInsight;
  /** 真是从词典里查到的（不是兜底示例）。 */
  matched: boolean;
}

export async function lookupWordInsight(
  word: string,
): Promise<DictionaryLookupResult> {
  try {
    const response = await api.dictionary(word);
    if (!response.fallback) return { insight: response.insight, matched: true };
  } catch {
    // 本机词典服务不在：往下一路走。
  }

  const offline = await lookupOfflineDictionary(word);
  if (offline) return { insight: offline, matched: true };

  const online = await lookupOnlineDictionary(word);
  if (online) return { insight: online, matched: true };

  return {
    insight: { ...fallbackInsight(word), sourceLabel: "示例" },
    matched: false,
  };
}
